"use client";

import { interpolateColors, useCurrentFrame } from "remotion";
import { hexToRgba } from "@/registry/snap-cn/text-highlight";
import {
  resolveEasing,
  springEase,
  TEXT_REVEAL_PRESETS,
} from "@/registry/snap-cn/text-reveal";

/**
 * HookTitle — the 0–3 second scroll-stopping opener of a launch video.
 *
 * Research-encoded pacing: everything is all-in within `maxFrames` (default
 * 90 = 3s @ 30fps), the first frame already shows content (no logo or
 * black-screen opener), and the scene reads muted — the hook is the copy,
 * with one keyword emphasized in accent blue.
 */

export type HookTitleStyle = "cut-in" | "build" | "stat";

export type HookTitleAccentStyle = "marker" | "color";

export type HookTitleAspect = "wide" | "square" | "vertical";

export type HookTitleTheme = "light" | "dark";

/* ------------------------------------------------------------------ */
/* Pure helpers (unit tested)                                          */
/* ------------------------------------------------------------------ */

/** Frames the hard-cut micro-settle takes. */
export const SETTLE_DURATION = 9;

/** Smallest pacing guard we honor — below this a hook can't breathe. */
export const MIN_MAX_FRAMES = 30;

/** Frames of visual rest guaranteed after the last movement. */
export const HOOK_HOLD = 6;

export const HOOK_THEMES: Record<
  HookTitleTheme,
  { canvas: string; text: string; muted: string }
> = {
  light: { canvas: "#FAFAFA", text: "#101828", muted: "#667085" },
  dark: { canvas: "#0A0A0B", text: "#FAFAFA", muted: "#A1A1AA" },
};

/** Type scale + measure per output aspect (composition size stays yours). */
export const HOOK_ASPECTS: Record<
  HookTitleAspect,
  { fontScale: number; padding: string; maxWidth: string }
> = {
  wide: { fontScale: 1, padding: "0 8%", maxWidth: "88%" },
  square: { fontScale: 0.88, padding: "0 8%", maxWidth: "92%" },
  vertical: { fontScale: 0.76, padding: "0 9%", maxWidth: "94%" },
};

/** Lowercase and strip leading/trailing punctuation for word matching. */
export function normalizeWord(word: string): string {
  return word.toLowerCase().replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, "");
}

/**
 * Find `accentWord` (one or more words, case- and punctuation-insensitive)
 * as a contiguous run inside `words`. Returns inclusive indices or null.
 */
export function findAccentRange(
  words: string[],
  accentWord: string | undefined,
): { start: number; end: number } | null {
  if (!accentWord) return null;
  const target = accentWord.split(/\s+/).map(normalizeWord).filter(Boolean);
  if (target.length === 0) return null;
  const norm = words.map(normalizeWord);
  for (let i = 0; i + target.length <= norm.length; i++) {
    if (target.every((t, j) => norm[i + j] === t)) {
      return { start: i, end: i + target.length - 1 };
    }
  }
  return null;
}

export interface HookUnit {
  text: string;
  isAccent: boolean;
}

/**
 * Group words into animation units. The accent phrase collapses into a
 * single unit so the marker can sweep it as one continuous stroke.
 */
export function buildUnits(
  words: string[],
  range: { start: number; end: number } | null,
): HookUnit[] {
  if (!range) return words.map((w) => ({ text: w, isAccent: false }));
  const units: HookUnit[] = [];
  for (let i = 0; i < range.start; i++) {
    units.push({ text: words[i], isAccent: false });
  }
  units.push({
    text: words.slice(range.start, range.end + 1).join(" "),
    isAccent: true,
  });
  for (let i = range.end + 1; i < words.length; i++) {
    units.push({ text: words[i], isAccent: false });
  }
  return units;
}

export interface StatParts {
  prefix: string;
  value: number | null;
  decimals: number;
  suffix: string;
}

/** Split a stat string like "9 hrs" or "1.5x" around its first number. */
export function parseStat(raw: string): StatParts {
  const m = raw.match(/-?\d+(?:\.\d+)?/);
  if (!m || m.index === undefined) {
    return { prefix: raw, value: null, decimals: 0, suffix: "" };
  }
  return {
    prefix: raw.slice(0, m.index),
    value: Number.parseFloat(m[0]),
    decimals: m[0].split(".")[1]?.length ?? 0,
    suffix: raw.slice(m.index + m[0].length),
  };
}

/**
 * The stat string at count-up progress `p` (0..1). Non-numeric strings are
 * returned unchanged; decimal places of the source literal are preserved.
 */
export function statAt(raw: string, p: number): string {
  const { prefix, value, decimals, suffix } = parseStat(raw);
  if (value === null) return prefix;
  const clamped = Math.max(0, Math.min(1, p));
  return `${prefix}${(value * clamped).toFixed(decimals)}${suffix}`;
}

export interface HookScheduleInput {
  style: HookTitleStyle;
  /** Number of animation units in the title line. */
  unitCount: number;
  /** Pacing guard: all motion completes by this frame (min 30). */
  maxFrames: number;
  hasAccent: boolean;
}

export interface HookSchedule {
  statStart: number;
  statDuration: number;
  titleStart: number;
  wordStagger: number;
  wordDuration: number;
  accentStart: number;
  accentDuration: number;
  /** Last frame on which anything still moves. Always <= the guard. */
  allInBy: number;
}

/**
 * Research-encoded pacing guard. Whatever the style and word count, the
 * whole hook — stat drop, title entrance, accent sweep — lands inside
 * `max(30, maxFrames)` with `HOOK_HOLD` frames of rest to spare.
 */
export function hookSchedule(input: HookScheduleInput): HookSchedule {
  const guard = Math.max(MIN_MAX_FRAMES, Math.round(input.maxFrames));
  const n = Math.max(1, input.unitCount);
  const build = TEXT_REVEAL_PRESETS["staggered-fade-up"];
  const buildDuration = build.enterDuration ?? 12;
  const buildStagger = build.stagger ?? 4;

  const statStart = 0;
  let statDuration = 0;
  let titleStart = 0;
  if (input.style === "stat") {
    statDuration = Math.min(18, Math.round(guard * 0.2));
    titleStart = Math.max(6, Math.round(statDuration * 0.66));
  }

  let wordStagger = 0;
  let wordDuration = SETTLE_DURATION;
  if (input.style !== "cut-in") {
    wordDuration = buildDuration;
    const buildWindow = Math.max(
      wordDuration,
      Math.round(guard * 0.45) - titleStart,
    );
    wordStagger =
      n > 1
        ? Math.max(
            0,
            Math.min(
              buildStagger,
              Math.floor((buildWindow - wordDuration) / (n - 1)),
            ),
          )
        : 0;
  }
  const titleEnd = titleStart + wordDuration + wordStagger * (n - 1);

  let accentStart = 0;
  let accentDuration = 0;
  if (input.hasAccent) {
    accentStart =
      input.style === "cut-in"
        ? SETTLE_DURATION - 2
        : titleEnd - Math.round(wordDuration / 3);
    accentStart = Math.max(0, Math.min(accentStart, guard - HOOK_HOLD - 10));
    accentDuration = Math.max(8, Math.min(24, guard - HOOK_HOLD - accentStart));
  }

  const allInBy = Math.max(
    titleEnd,
    statStart + statDuration,
    input.hasAccent ? accentStart + accentDuration : 0,
  );

  return {
    statStart,
    statDuration,
    titleStart,
    wordStagger,
    wordDuration,
    accentStart,
    accentDuration,
    allInBy,
  };
}

/* ------------------------------------------------------------------ */
/* Component                                                           */
/* ------------------------------------------------------------------ */

export interface HookTitleProps {
  /** The hook line. Keep it under ~10 words — the guard will pace it either way. */
  text: string;
  /** Word or phrase inside `text` to emphasize (case-insensitive). */
  accentWord?: string;
  /** How the keyword is emphasized. */
  accentStyle?: HookTitleAccentStyle;
  accentColor?: string;
  /** Entrance style. `stat` drops a counter number above the line first. */
  style?: HookTitleStyle;
  /** Stat style only: the number that drops in first, e.g. "9 hrs". */
  statValue?: string;
  /** Pacing guard — all motion completes within this many frames (min 30). */
  maxFrames?: number;
  /** Type scale + measure preset for the output aspect. */
  aspect?: HookTitleAspect;
  theme?: HookTitleTheme;
  /** Canvas fill. Defaults to the theme canvas; pass "transparent" to overlay. */
  background?: string;
  fontSize?: number;
  fontWeight?: number | string;
  speed?: number;
  className?: string;
}

const FONT_STACK =
  "var(--font-geist-sans), Inter, -apple-system, BlinkMacSystemFont, sans-serif";

const clamp01 = (v: number) => Math.max(0, Math.min(1, v));

export function HookTitle({
  text,
  accentWord,
  accentStyle = "marker",
  accentColor = "#266DF0",
  style = "cut-in",
  statValue = "9 hrs",
  maxFrames = 90,
  aspect = "wide",
  theme = "light",
  background,
  fontSize = 84,
  fontWeight = 700,
  speed = 1,
  className,
}: HookTitleProps) {
  const frame = useCurrentFrame() * speed;
  const palette = HOOK_THEMES[theme];
  const sizing = HOOK_ASPECTS[aspect];

  const words = text.split(/\s+/).filter((w) => w.length > 0);
  const range = findAccentRange(words, accentWord);
  const units = buildUnits(words, range);
  const schedule = hookSchedule({
    style,
    unitCount: units.length,
    maxFrames,
    hasAccent: range !== null,
  });

  const settleEase = resolveEasing("smooth");
  const buildEase = resolveEasing("snappy");
  const sweepEase = resolveEasing("smooth");
  const buildDistance = TEXT_REVEAL_PRESETS["staggered-fade-up"].distance ?? 20;

  const size = fontSize * sizing.fontScale;
  const sweepP = range
    ? sweepEase(
        clamp01((frame - schedule.accentStart) / schedule.accentDuration),
      )
    : 0;
  const accentTextColor =
    accentStyle === "color"
      ? interpolateColors(clamp01(sweepP), [0, 1], [palette.text, accentColor])
      : palette.text;

  // Stat drop (stat style only): hard cut in, high-damping settle, count up.
  const statLocal = frame - schedule.statStart;
  const statSettle = springEase(clamp01(statLocal / schedule.statDuration));
  const statCount = settleEase(clamp01(statLocal / schedule.statDuration));

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: background ?? palette.canvas,
        padding: sizing.padding,
        fontFamily: FONT_STACK,
      }}
    >
      <div
        className={className}
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: size * 0.24,
          maxWidth: sizing.maxWidth,
        }}
      >
        {style === "stat" && (
          <div
            style={{
              fontSize: size * 1.45,
              fontWeight: 700,
              letterSpacing: "-0.02em",
              lineHeight: 1,
              color: accentColor,
              opacity: statLocal >= 0 ? 1 : 0,
              translate: `0 ${-14 * (1 - statSettle)}px`,
              fontVariantNumeric: "tabular-nums",
            }}
          >
            {statAt(statValue, statCount)}
          </div>
        )}
        <div
          style={{
            fontSize: size,
            fontWeight,
            color: palette.text,
            letterSpacing: "-0.02em",
            lineHeight: 1.08,
            textAlign: "center",
          }}
        >
          {units.map((unit, i) => {
            const local =
              frame - schedule.titleStart - i * schedule.wordStagger;
            const p = clamp01(local / schedule.wordDuration);
            const hardCut = style === "cut-in";
            const enterP = hardCut ? settleEase(p) : buildEase(p);
            const visible = local >= 0;
            const y = (hardCut ? 8 : buildDistance) * (1 - enterP);
            const opacity = hardCut ? (visible ? 1 : 0) : visible ? enterP : 0;

            const content = unit.isAccent ? (
              <span style={{ position: "relative", whiteSpace: "pre" }}>
                {accentStyle === "marker" && (
                  <span
                    aria-hidden
                    style={{
                      position: "absolute",
                      inset: "-0.02em -0.12em",
                      background: hexToRgba(accentColor, 0.2),
                      borderRadius: "0.12em",
                      transformOrigin: "left center",
                      transform: `scaleX(${sweepP})`,
                    }}
                  />
                )}
                <span style={{ position: "relative", color: accentTextColor }}>
                  {unit.text}
                </span>
              </span>
            ) : (
              unit.text
            );

            return (
              <span
                // biome-ignore lint/suspicious/noArrayIndexKey: units are positional and never reorder
                key={i}
                style={{
                  display: "inline-block",
                  whiteSpace: "pre",
                  backfaceVisibility: "hidden",
                  opacity,
                  translate: `0 ${y}px`,
                  marginRight: i < units.length - 1 ? "0.26em" : undefined,
                }}
              >
                {content}
              </span>
            );
          })}
        </div>
      </div>
    </div>
  );
}
